hooks.command:
$j=[Console]::In.ReadToEnd()
$m=[regex]::Matches($j,'from //Codex/main/[^"]*?(CurrentPlan|[a-z0-9-]+-backlog|[a-z]+-workplan)\.md')
if($m.Count -gt 0){
  $names=($m | ForEach-Object { $_.Groups[1].Value } | Sort-Object -Unique) -join ', '
  @{hookSpecificOutput=@{hookEventName='PostToolUse';additionalContext="MERGE-DOWN CHANGED OPEN-WORK REGISTERS: $names. Read each one NOW, before continuing, and re-check whether the item you are working on is still open or has moved owner. CurrentPlan is the fleet's ONLY cross-lane register of open work; a backlog is its app's or quire's. A *-workplan is EMPTY BY DESIGN and holds only a session's in-flight lane state -- if one arrived carrying work items, standing facts or messages to other lanes, that is a defect: the content belongs in CurrentPlan, a backlog, or the doc that owns the subject. Do not defer this to the next init -- a register read once at init is remembered wrong, which is how a live item gets missed or done twice."}} | ConvertTo-Json -Compress -Depth 5
}
